insert into public.journeys (slug, title, summary, minutes, steps, sort) values ('calm-when-overwhelmed', 'A moment of calm when you feel overwhelmed', 'A short guided pause to slow down, name what is happening, and choose one small next step.', 8, '[{"title":"Pause and notice","body":"Stop what you can for a minute. Put both feet on the floor and **breathe out slowly**, longer than you breathe in. Do this a few times.","action":"pause"},{"title":"Name what you feel","body":"Try to put a word on it: *stressed, scared, angry, sad, tired.* Naming a feeling is not the same as agreeing with it.","action":"reflect","link_slug":"understanding-emotions","reflect_prompt":"What am I feeling right now, and where do I feel it in my body?"},{"title":"Learn about stress","body":"Stress is a normal response, and it can feel intense. Read a short piece on what stress is and what can help.","action":"read","link_slug":"stress"},{"title":"Sort what you can influence","body":"Make two short lists: things you **can** influence today, and things you **cannot**. Circle one thing from the first list.","action":"reflect","link_slug":"control","reflect_prompt":"What is one thing I can influence today?"},{"title":"Choose one small step","body":"Pick one small action for the next hour, such as water, a walk, a message to someone, or a task you can finish in five minutes. If you feel unsafe, please see **Get Help Now**.","action":"plan","reflect_prompt":"What small action would support my well-being today?"}]'::jsonb, 0) on conflict do nothing;
insert into public.journeys (slug, title, summary, minutes, steps, sort) values ('untangling-a-thought', 'Untangling a thought', 'Slow down a stressful thought, separate facts from assumptions, and look for another possible view.', 10, '[{"title":"Write the thought down","body":"Write the thought exactly as it shows up, like *\"I always mess things up.\"* Seeing it on the screen can give it some distance.","action":"reflect","reflect_prompt":"What is the thought I keep returning to?"},{"title":"Separate facts from assumptions","body":"Which parts could a neutral observer confirm? Which parts are a guess, a prediction, or a feeling presented as a fact?","action":"read","link_slug":"facts-vs-assumptions"},{"title":"Ask what else might be true","body":"Look for at least one other explanation, even if it feels less likely right now. You do not have to believe it yet.","action":"reflect","link_slug":"reframing","reflect_prompt":"What else might be true? What would I say to a friend in my situation?"},{"title":"Be gentle with yourself","body":"Notice the tone of your inner voice. Try saying something to yourself that you would say to someone you care about.","action":"read","link_slug":"self-compassion"},{"title":"Decide on a next step","body":"Is there one small thing you can do, check, or ask? Write it down.","action":"plan","reflect_prompt":"What is one small step I can take today?"}]'::jsonb, 1) on conflict do nothing;
insert into public.journeys (slug, title, summary, minutes, steps, sort) values ('reconnecting-with-someone', 'Reconnecting with someone', 'A gentle path from thinking about someone to sending a simple message.', 10, '[{"title":"Think of one person","body":"Think of someone you have drifted from, or someone who has been kind to you. It does not have to be a big relationship.","action":"reflect","reflect_prompt":"Who comes to mind when I think of someone I would like to hear from?"},{"title":"Notice what gets in the way","body":"Worries like *\"they are too busy\"* or *\"it will be awkward\"* are common. Are they facts, or assumptions?","action":"read","link_slug":"facts-vs-assumptions"},{"title":"Start with appreciation","body":"What do you appreciate about this person? Gratitude can make a message feel easier to write and warmer to receive.","action":"reflect","link_slug":"gratitude","reflect_prompt":"What is one thing I appreciate about them?"},{"title":"Reach out","body":"Send a short, low-pressure message, such as *\"Hey, I was thinking about you. How have you been?\"* A reply is not required for it to be worth sending.","action":"reach-out"},{"title":"Plan a follow-up","body":"If it goes well, pick a small next step, like a call or coffee. If you do not hear back, that is not a verdict on you or the relationship.","action":"plan"}]'::jsonb, 2) on conflict do nothing;
commit;
